catalogue/text::joined.text:
/// The operands' text joined, a number's text as coercion gives it. An operand's error is the
/// result, the left operand's first, before any operand is read as text: no operand's text can be
/// an error. A result longer than a cell holds is cut to its first 32767 UTF-16 code units, even
/// where the cut parts a surrogate pair. Only a top-level & in a cell was measured: the
/// mixed_operands rows of cfunc-m1.2's oracle workbook =C2&"b", with 32767 characters in C2, and
/// C1, with 32766 characters, joined with a text of the one character U+1F600. The cut of an &
/// whose result another operator or function reads is unmeasured.
fn joined(site: &Site<'_>, arguments: &[CalcValue]) -> Step<CalcValue> {
    site.scalar_operands(arguments)?;
    if let Some(code) = arguments.iter().find_map(|argument| match argument.core_ref() {
        CoreRef::Error(code) => Some(code),
        _ => None,
    }) {
        return Err(Exit::Error(code));
    }
    let left = site.argument(0, coerce::text(&arguments[0]))?;
    let right = site.argument(1, coerce::text(&arguments[1]))?;
    let mut units = Vec::with_capacity(left.len() + right.len());
    units.extend_from_slice(&left);
    units.extend_from_slice(&right);
    // Measured for a top-level & only (see above).
    units.truncate(EXCEL_TEXT_MAX_UTF16_CODE_UNITS);
    Ok(CalcValue::text(ExcelText::from_utf16_code_units(units)))
}

coerce::text.text:
/// The value as text to concatenate, in UTF-16 code units: text as it is, a number as its text
/// ([`number_text`], Excel's text with `.` as the decimal separator and no column width), TRUE
/// and FALSE as those words, Empty and Missing as empty text, an error as itself. Every finite
/// number has text under that model, including its documented near-tie mismatches. A number
/// qualified as Excel's exponent-carry rounding result uses its measured General
/// rendering. Other nonfinite numbers are refused as not modelled.
pub(crate) fn text(value: &CalcValue) -> Result<Cow<'_, [u16]>, Stop> {
    match value.core_ref() {
        CoreRef::Text(text) => Ok(Cow::Borrowed(text.utf16_code_units())),
        CoreRef::Number(n) if value.is_excel_overflow() => {
            let profile = crate::locale::format_profile(crate::locale::LocaleId::EnZa);
            Ok(Cow::Owned(crate::format::general(&profile, n).encode_utf16().collect()))
        }
        CoreRef::Number(n) if n.is_finite() => number_text::text(n)
            .map(|text| Cow::Owned(text.encode_utf16().collect()))
            .ok_or(Stop::NotModelled),
        CoreRef::Logical(true) => Ok(Cow::Borrowed(&TRUE_TEXT)),
        CoreRef::Logical(false) => Ok(Cow::Borrowed(&FALSE_TEXT)),
        CoreRef::Empty | CoreRef::Missing => Ok(Cow::Borrowed(&[])),
        CoreRef::Error(code) => Err(Stop::Error(code)),
        CoreRef::Number(_) | CoreRef::Array(_) | CoreRef::Reference(_) => {
            Err(Stop::NotModelled)
        }
    }
}

