fn pack_raw(neg: bool, biased: u16, sig: u64) -> Ext80 {
    let mut out = [0u8; 10];
    out[..8].copy_from_slice(&sig.to_le_bytes());
    let se = biased | if neg { 0x8000 } else { 0 };
    out[8..].copy_from_slice(&se.to_le_bytes());
    Ext80(out)
}

