pub fn acosh_kernel(n: f64) -> Result<f64, WorksheetErrorCode> {
    if n < 1.0 {
        return Err(WorksheetErrorCode::Num);
    }
    // Inverse-problem identity, live Excel 16.0 b20228 Range.Value2:
    // ACOSH(x) == LN(x+SQRT(x*x-1)) on 29/29 including 1, 1+1ulp, and
    // large finite x. SQRT((x-1)*(x+1)) is not the graph (18/24).
    // When x*x overflows, Excel publishes #NUM! (ACOSH(1e200)), the same
    // intermediate overflow ASINH uses.
    if !(n * n).is_finite() {
        return Err(WorksheetErrorCode::Num);
    }
    Ok(crate::ported::excel_numeric::excel_log(n + (n * n - 1.0).sqrt()))
}

ported/acot::acot_kernel.text:
pub fn acot_kernel(n: f64) -> Result<f64, WorksheetErrorCode> {
    // W111 distinguishes this reciprocal/angle graph from direct atan2 and
    // from a binary64-only reciprocal. It is an observed arithmetic model,
    // not a claim about Excel internals or universal FPATAN parity.
    if n == 0.0 {
        return Ok(std::f64::consts::FRAC_PI_2);
    }
    let reciprocal = crate::ported::excel_numeric::excel_x87_recip(n);
    let angle = crate::ported::excel_numeric::excel_atan_reduced(reciprocal);
    let result = if n < 0.0 {
        angle + std::f64::consts::PI
    } else {
        angle
    };
    Ok(if result.abs() < f64::MIN_POSITIVE {
        0.0
    } else {
        result
    })
}

