decimal::ExactDecimal::read.text:
/// How the rounding and integer functions read a finite number. When its shortest decimal
/// that converts back to the same binary64 has at most 15 significant digits, the number is
/// that decimal: every number typed into a cell, which Excel reads to 15 significant digits,
/// reads back so (2.675, whose binary64 lies below 2.675, reads as 2.675). Any other number is
/// the exact value of its binary64 (0.1+0.2 reads as 0.3000000000000000444...). Zero of
/// either sign reads as +0.
pub(crate) fn read(x: f64) -> ExactDecimal {
    let negative = x < 0.0;
    let magnitude = x.abs();
    if magnitude == 0.0 {
        return ExactDecimal {
            negative: false,
            coefficient: Natural::zero(),
            exponent: 0,
        };
    }
    let shortest = format!("{magnitude:e}");
    let (mantissa, power) = shortest
        .split_once('e')
        .expect("an exponent in the shortest form");
    let power: i32 = power.parse().expect("a decimal exponent");
    let (whole, fraction) = mantissa.split_once('.').unwrap_or((mantissa, ""));
    if whole.len() + fraction.len() <= SHOWN_DIGITS {
        let coefficient: u64 = format!("{whole}{fraction}")
            .parse()
            .expect("at most 15 decimal digits");
        let scale = i32::try_from(fraction.len()).expect("a short fraction");
        return ExactDecimal {
            negative,
            coefficient: Natural::from_u64(coefficient),
            exponent: power - scale,
        };
    }
    ExactDecimal::binary(x)
}

format/datetime::has_invalid_exponent.text:
pub(crate) fn has_invalid_exponent(section: &str) -> bool {
    section.contains('E') && tokenize_datetime_format(section, None).iter().any(|part| {
        matches!(part, DateTimePart::Token { kind: DateTimeTokenKind::UpperExponent, .. })
    })
}

format/datetime::looks_like_datetime_for.text:
pub(crate) fn looks_like_datetime_format(section: &str) -> bool {
    let parts = tokenize_datetime_format(section, None);
    let has_datetime_token = parts.iter().any(|part| match part {
        DateTimePart::Token { .. } => true,
        DateTimePart::Literal(_) => false,
    });
    has_datetime_token
        && !section.contains('#')
        && !without_subseconds(section).contains('0')
        && !section.contains('?')
}

format/datetime::without_subseconds.text:
/// The section with the decimal places of a seconds token (`s.0`, `ss.00`, `[ss].000`) removed:
/// the zeros left over belong to no date or time token.
pub(crate) fn without_subseconds(section: &str) -> String {
    let chars: Vec<char> = section.chars().collect();
    let mut out = String::new();
    let mut index = 0;
    while index < chars.len() {
        out.push(chars[index]);
        let after_second = matches!(chars[index], 's' | 'S' | ']')
            && (chars[index] != ']' || out.to_ascii_lowercase().ends_with("s]"));
        if after_second && chars.get(index + 1) == Some(&'.') && chars.get(index + 2) == Some(&'0') {
            index += 2;
            while chars.get(index) == Some(&'0') {
                index += 1;
            }
            continue;
        }
        index += 1;
    }
    out
}

format/datetime::render_with_datetime_to.text:
pub(crate) fn render_with_datetime_tokens(
    profile: &FormatProfile,
    date_system: WorkbookDateSystem,
    value: f64,
    section: &str,
    name_locale: Option<LocaleId>,
    untagged_locale: bool,
) -> Option<String> {
    if !value.is_finite() {
        return None;
    }

    let parts = classify_minute_tokens(tokenize_datetime_format(section, Some(profile)));
    if !parts
        .iter()
        .any(|part| matches!(part, DateTimePart::Token { .. }))
    {
        return None;
    }

    let has_date_tokens = parts.iter().any(|part| {
        matches!(
            part,
            DateTimePart::Token {
                kind: DateTimeTokenKind::Year | DateTimeTokenKind::Month | DateTimeTokenKind::Day
                    | DateTimeTokenKind::Era | DateTimeTokenKind::EraYear | DateTimeTokenKind::UpperExponent,
                ..
            }
        )
    });
    let has_ampm = parts.iter().any(|part| {
        matches!(
            part,
            DateTimePart::Token {
                kind: DateTimeTokenKind::AmPmUpper | DateTimeTokenKind::AmPmLower,
                ..
            }
        )
    });
    // The time is rounded to the places of a sub-second token, when the section has one (Excel
    // 16.0.20430, dc-uar: TEXT(9000.79348,"mm:ss.00") is 02:36.67).
    let places = parts
        .iter()
        .find_map(|part| match part {
            DateTimePart::Token {
                kind: DateTimeTokenKind::SubSecond,
                width,
            } => Some(*width),
            _ => None,
        })
        .unwrap_or(0);
    if places > 3 {
        return None;
    }
    let time = TimeParts::from_serial(value, places as u32);
    // The date is the day the rounded time falls in: a time that rounds up to midnight shows the
    // next day (Excel 16.0.20430, dc-uar: TEXT(0.99999999,"yyyy-mm-dd hh:mm:ss.00") is
    // 1900-01-01 00:00:00.00).
    let date = if has_date_tokens {
        Some(ymd_from_excel_serial(
            date_system,
            time.elapsed_seconds.div_euclid(86_400) as f64,
        )?)
    } else {
        None
    };
    // TEXT follows the same serial calendar as WEEKDAY, including fictitious
    // 1900-02-29. Use the day after the existing time rounding, not Gregorian y/m/d.
    let weekday_index = date.and_then(|_| {
        let serial = time.elapsed_seconds.div_euclid(86_400) as f64
            + if date_system == WorkbookDateSystem::System1904 {
                crate::ported::date_kernels::OFFSET_1904
            } else {
                0.0
            };
        crate::ported::date_kernels::weekday(serial, None)
            .ok()
            .map(|day| day as usize - 1)
    });
    // A locale tag selects names, while separators and other formatting fields remain those
    // of the workbook profile. Fn1 measured German, French, Japanese and Russian names.
    let names_profile = FormatProfile { id: name_locale.unwrap_or(profile.id), ..*profile };

    let mut rendered = String::new();
    for part in parts {
        match part {
            DateTimePart::Literal(text) => {
                rendered.push_str(&render_datetime_literal(profile, &text))
            }
            DateTimePart::Token { kind, width } => {
                let fragment = match kind {
                    DateTimeTokenKind::Year => {
                        let (year, _, _) = date?;
                        if width <= 2 {
                            format!("{:02}", year.rem_euclid(100))
                        } else {
                            format!("{year:04}")
                        }
                    }
                    DateTimeTokenKind::Month => {
                        let (_, month, _) = date?;
                        match width {
                            1 => month.to_string(),
                            2 => format!("{month:02}"),
                            3 => month_name(&names_profile, month, true, name_locale.is_some()),
                            _ => month_name(&names_profile, month, false, name_locale.is_some()),
                        }
                    }
                    DateTimeTokenKind::Minute => {
                        if width <= 1 {
                            time.minute.to_string()
                        } else {
                            format!("{:02}", time.minute)
                        }
                    }
                    DateTimeTokenKind::Day => {
                        let (_, _, day) = date?;
                        match width {
                            1 => day.to_string(),
                            2 => format!("{day:02}"),
                            3 => weekday_name(&names_profile, weekday_index?, true, name_locale.is_some()),
                            _ => weekday_name(&names_profile, weekday_index?, false, name_locale.is_some()),
                        }
                    }
                    DateTimeTokenKind::Hour => {
                        let hour = if has_ampm {
                            let hour = time.hour % 12;
                            if hour == 0 { 12 } else { hour }
                        } else {
                            time.hour
                        };
                        if width <= 1 {
                            hour.to_string()
                        } else {
                            format!("{hour:02}")
                        }
                    }
                    DateTimeTokenKind::Second => {
                        if width <= 1 {
                            time.second.to_string()
                        } else {
                            format!("{:02}", time.second)
                        }
                    }
                    DateTimeTokenKind::ElapsedHour => {
                        format_elapsed(value, time.elapsed_hours, width)
                    }
                    DateTimeTokenKind::ElapsedMinute => {
                        format_elapsed(value, time.elapsed_minutes, width)
                    }
                    DateTimeTokenKind::ElapsedSecond => {
                        format_elapsed(value, time.elapsed_seconds, width)
                    }
                    DateTimeTokenKind::SubSecond => {
                        format!(".{:0width$}", time.subsecond)
                    }
                    DateTimeTokenKind::AmPmUpper => {
                        super::designator(profile, time.hour < 12).to_string()
                    }
                    DateTimeTokenKind::AmPmLower => {
                        super::designator(profile, time.hour < 12).to_string()
                    }
                    DateTimeTokenKind::Era | DateTimeTokenKind::EraYear | DateTimeTokenKind::UpperExponent => {
                        let (year, month, day) = date?;
                        // Fn5 zero section and fn8 width/era-boundary controls:
                        // an untagged e is Gregorian; g contributes no era name.
                        if untagged_locale && super::measured_host(profile) {
                            match kind {
                                DateTimeTokenKind::EraYear => { rendered.push_str(&year.to_string()); continue; }
                                DateTimeTokenKind::Era => continue,
                                _ => return None,
                            }
                        }
                        // Fn3 measures g/gg/ggg and e/ee on both sides of the
                        // Heisei/Reiwa transition. Calendar start dates are public facts:
                        // https://www.npb.go.jp/en/products/gazette/books/kanpo_history.html
                        if name_locale != Some(LocaleId::JaJp) { return None; }
                        let (base_year, latin, short, long) = if (year, month, day) >= (2019, 5, 1) {
                            (2018, "R", "令", "令和")
                        } else if (year, month, day) >= (1989, 1, 8) {
                            (1988, "H", "平", "平成")
                        } else {
                            return None;
                        };
                        match (kind, width) {
                            (DateTimeTokenKind::Era, 1) => latin.to_owned(),
                            (DateTimeTokenKind::Era, 2) => short.to_owned(),
                            (DateTimeTokenKind::Era, 3) => long.to_owned(),
                            (DateTimeTokenKind::EraYear | DateTimeTokenKind::UpperExponent, 1) => (year - base_year).to_string(),
                            (DateTimeTokenKind::EraYear | DateTimeTokenKind::UpperExponent, 2) => format!("{:02}", year - base_year),
                            _ => return None,
                        }
                    }
                };
                rendered.push_str(&fragment);
            }
        }
    }

    Some(rendered)
}

format/datetime::tokenize_datetime_forma.text:
fn tokenize_datetime_format(section: &str, profile: Option<&FormatProfile>) -> Vec<DateTimePart> {
    let chars: Vec<char> = section.chars().collect();
    let mut parts = Vec::new();
    let mut literal = String::new();
    let mut index = 0;
    let mut in_quotes = false;
    let mut quoted_literal = String::new();
    let mut quoted_escape = false;

    while index < chars.len() {
        let ch = chars[index];
        if ch == '"' {
            if in_quotes {
                literal.push_str(if quoted_escape { &quoted_literal } else {
                    profile.map_or(quoted_literal.as_str(), |p| super::currency_literal(p, &quoted_literal))
                });
                quoted_escape = false;
                quoted_literal.clear();
            }
            in_quotes = !in_quotes;
            index += 1;
            continue;
        }
        if ch == '\\' {
            if let Some(next) = chars.get(index + 1) {
                if in_quotes { quoted_literal.push(*next); quoted_escape = true; } else { literal.push(*next); }
                index += 2;
            } else {
                index += 1;
            }
            continue;
        }
        if in_quotes {
            quoted_literal.push(ch);
            index += 1;
            continue;
        }

        if let Some((kind, width, consumed)) = elapsed_token_at(&chars, index) {
            push_literal(&mut parts, &mut literal);
            parts.push(DateTimePart::Token { kind, width });
            index += consumed;
            continue;
        }

        if ch == '.'
            && chars.get(index + 1) == Some(&'0')
            && matches!(
                parts.last(),
                Some(DateTimePart::Token {
                    kind: DateTimeTokenKind::Second | DateTimeTokenKind::ElapsedSecond,
                    ..
                })
            )
            && literal.is_empty()
        {
            let width = chars[index + 1..].iter().take_while(|c| **c == '0').count();
            parts.push(DateTimePart::Token {
                kind: DateTimeTokenKind::SubSecond,
                width,
            });
            index += 1 + width;
            continue;
        }

        let remaining: String = chars[index..].iter().take(5).collect();
        if remaining.eq_ignore_ascii_case("am/pm") {
            push_literal(&mut parts, &mut literal);
            let kind = if remaining == "am/pm" {
                DateTimeTokenKind::AmPmLower
            } else {
                DateTimeTokenKind::AmPmUpper
            };
            parts.push(DateTimePart::Token { kind, width: 5 });
            index += 5;
            continue;
        }

        let lower = ch.to_ascii_lowercase();
        let kind = match lower {
            'y' => Some(DateTimeTokenKind::Year),
            'm' => Some(DateTimeTokenKind::Month),
            'd' => Some(DateTimeTokenKind::Day),
            'h' => Some(DateTimeTokenKind::Hour),
            's' => Some(DateTimeTokenKind::Second),
            'g' => Some(DateTimeTokenKind::Era),
            'e' if ch == 'E' && !matches!(chars.get(index + 1), Some('+' | '-')) => Some(DateTimeTokenKind::UpperExponent),
            'e' => Some(DateTimeTokenKind::EraYear),
            _ => None,
        };

        if let Some(kind) = kind {
            let width = chars[index..]
                .iter()
                .take_while(|candidate| candidate.to_ascii_lowercase() == lower)
                .count();
            // Mixed e/E runs are invalid in untagged host formats too.
            // Tagged Japanese rendering keeps its prior case-insensitive width.
            let kind = if lower == 'e' && chars[index..index + width].contains(&'E')
                && (width > 1 || !matches!(chars.get(index + width), Some('+' | '-'))) {
                DateTimeTokenKind::UpperExponent
            } else { kind };
            push_literal(&mut parts, &mut literal);
            parts.push(DateTimePart::Token { kind, width });
            index += width;
        } else {
            let atom = ch.to_string();
            literal.push_str(profile.map_or(atom.as_str(), |p| super::currency_literal(p, &atom)));
            index += 1;
        }
    }

    // Preserve the previous treatment of an unfinished quote.
    literal.push_str(&quoted_literal);
    push_literal(&mut parts, &mut literal);
    parts
}

format/datetime::elapsed_token_at.text:
fn elapsed_token_at(chars: &[char], index: usize) -> Option<(DateTimeTokenKind, usize, usize)> {
    if chars.get(index) != Some(&'[') {
        return None;
    }
    let close = chars[index + 1..].iter().position(|ch| *ch == ']')? + index + 1;
    let token: String = chars[index + 1..close].iter().collect();
    let lower = token.to_ascii_lowercase();
    if lower.is_empty() || !lower.chars().all(|ch| matches!(ch, 'h' | 'm' | 's')) {
        return None;
    }
    let first = lower.chars().next()?;
    if !lower.chars().all(|ch| ch == first) {
        return None;
    }
    let kind = match first {
        'h' => DateTimeTokenKind::ElapsedHour,
        'm' => DateTimeTokenKind::ElapsedMinute,
        's' => DateTimeTokenKind::ElapsedSecond,
        _ => return None,
    };
    Some((kind, lower.len(), close - index + 1))
}

format/datetime::classify_minute_tokens.text:
fn classify_minute_tokens(parts: Vec<DateTimePart>) -> Vec<DateTimePart> {
    let token_indexes: Vec<usize> = parts
        .iter()
        .enumerate()
        .filter_map(|(index, part)| matches!(part, DateTimePart::Token { .. }).then_some(index))
        .collect();
    let mut classified = parts;

    for (token_position, part_index) in token_indexes.iter().enumerate() {
        let DateTimePart::Token { kind, width } = classified[*part_index].clone() else {
            continue;
        };
        if kind != DateTimeTokenKind::Month {
            continue;
        }
        let previous_kind = token_position
            .checked_sub(1)
            .and_then(|previous| token_indexes.get(previous))
            .and_then(|index| token_kind(&classified[*index]));
        let next_kind = token_indexes
            .get(token_position + 1)
            .and_then(|index| token_kind(&classified[*index]));
        if previous_kind.is_some_and(is_time_neighbor) || next_kind.is_some_and(is_time_neighbor) {
            classified[*part_index] = DateTimePart::Token {
                kind: DateTimeTokenKind::Minute,
                width,
            };
        }
    }

    classified
}

format/datetime::token_kind.text:
fn token_kind(part: &DateTimePart) -> Option<DateTimeTokenKind> {
    match part {
        DateTimePart::Token { kind, .. } => Some(*kind),
        DateTimePart::Literal(_) => None,
    }
}

format/datetime::push_literal.text:
fn push_literal(parts: &mut Vec<DateTimePart>, literal: &mut String) {
    if !literal.is_empty() {
        parts.push(DateTimePart::Literal(std::mem::take(literal)));
    }
}

format/datetime::render_datetime_literal.text:
fn render_datetime_literal(profile: &FormatProfile, text: &str) -> String {
    text.replace('/', profile.date_separator)
        .replace(':', profile.time_separator)
}

format/datetime::format_elapsed.text:
fn format_elapsed(value: f64, magnitude: i64, width: usize) -> String {
    let prefix = if value.is_sign_negative() && magnitude != 0 {
        "-"
    } else {
        ""
    };
    let magnitude = magnitude.abs();
    if width <= 1 {
        format!("{prefix}{magnitude}")
    } else {
        format!("{prefix}{magnitude:0width$}")
    }
}

format/datetime::TimeParts::from_serial.text:
/// The time of day of a serial rounded to `places` decimal places of a second.
fn from_serial(value: f64, places: u32) -> Self {
    let unit = 10i64.pow(places);
    let total_units = (value * 86_400.0 * unit as f64).round() as i64;
    let total_seconds = total_units.div_euclid(unit);
    let seconds_in_day = total_seconds.rem_euclid(86_400);
    Self {
        hour: seconds_in_day / 3_600,
        minute: (seconds_in_day % 3_600) / 60,
        second: seconds_in_day % 60,
        elapsed_hours: total_seconds / 3_600,
        elapsed_minutes: total_seconds / 60,
        elapsed_seconds: total_seconds,
        subsecond: total_units.rem_euclid(unit),
    }
}

format::measured_host.text:
/// The host profiles measured by the scalar formatting questions.
fn measured_host(profile: &FormatProfile) -> bool {
    matches!(profile.id, LocaleId::EnZa | LocaleId::CurrentExcelHost)
}

format::currency_literal.text:
/// A literal atom exactly naming the measured currency ignores ASCII case.
/// Quoted longer words stay literal; unquoted characters arrive one at a time.
fn currency_literal<'a>(profile: &FormatProfile, text: &'a str) -> &'a str {
    if measured_host(profile) && profile.currency_symbol == "R" && text.eq_ignore_ascii_case("R") {
        profile.currency_symbol
    } else {
        text
    }
}

format::digits.text:
/// The magnitude of `x` rounded to 15 significant digits and then to `places` decimal places
/// (negative places round to tens, hundreds and so on), a half away from zero, as its integer
/// digits (no leading zero; empty for zero) and exactly `max(places, 0)` decimal digits.
pub(crate) fn digits(x: f64, places: i32) -> (String, String) {
    let first = fifteen(x.abs());
    let rounded = first.round_at(-places, Direction::Nearest).unwrap_or(first);
    split(&rounded, places.max(0) as usize)
}

format::fifteen.text:
/// FIXED/TEXT and concatenation share their first15-digit conversion. Reuse
/// its existing near-tie behavior, including the open dc-b1l.25 departures.
fn fifteen(x: f64) -> ExactDecimal {
    crate::number_text::decimal(x)
}

format::split.text:
/// A decimal's integer digits (without leading zeros) and `places` decimal digits.
fn split(decimal: &ExactDecimal, places: usize) -> (String, String) {
    if decimal.coefficient.is_zero() {
        return (String::new(), "0".repeat(places));
    }
    let digits = decimal.coefficient.digits();
    let exponent = decimal.exponent;
    let (whole, fraction) = if exponent >= 0 {
        (format!("{digits}{}", "0".repeat(exponent as usize)), String::new())
    } else {
        let point = digits.len() as i64 + exponent as i64;
        if point <= 0 {
            (String::new(), format!("{}{digits}", "0".repeat((-point) as usize)))
        } else {
            let point = point as usize;
            (digits[..point].to_owned(), digits[point..].to_owned())
        }
    };
    let whole = whole.trim_start_matches('0').to_owned();
    let mut fraction = fraction;
    fraction.truncate(places);
    while fraction.len() < places {
        fraction.push('0');
    }
    (whole, fraction)
}

format::grouped.text:
fn grouped(whole: &str, separator: &str) -> String {
    if whole.len() <= 3 {
        return whole.to_owned();
    }
    let mut out = String::new();
    let first = whole.len() % 3;
    if first > 0 {
        out.push_str(&whole[..first]);
    }
    let mut at = first;
    while at < whole.len() {
        if !out.is_empty() {
            out.push_str(separator);
        }
        out.push_str(&whole[at..at + 3]);
        at += 3;
    }
    out
}

format::general.text:
/// The General format's text: at most 11 characters besides the sign, as a cell of Excel's
/// standard column width shows a number. Public as [`crate::general_format`] for an app that
/// shows a value as a cell would.
pub fn general(profile: &FormatProfile, value: f64) -> String {
    const WIDTH: i64 = 11;
    if !value.is_finite() {
        if !value.is_nan() {
            return "#NUM!".to_owned();
        }
        // Excel's retained exponent-field-2047 readings show two significant digits,
        // without a minus sign, even when the stored encoding has its sign bit set.
        let exact = ExactDecimal::binary(value);
        let exponent = exact.magnitude();
        let (mantissa, carry) = significant(&exact, 2);
        let (head, tail) = mantissa.split_at(1);
        let tail = tail.trim_end_matches('0');
        let point = if tail.is_empty() { "" } else { profile.decimal_separator };
        return format!("{head}{point}{tail}E+{}", i64::from(exponent) + carry);
    }
    if value == 0.0 || value.is_subnormal() {
        return "0".to_owned();
    }
    let sign = if value < 0.0 { "-" } else { "" };
    let magnitude = value.abs();
    let first = fifteen(magnitude);
    let length = first.coefficient.digits().len() as i64;
    // The value is 0.d1d2... * 10^point.
    let point = length + first.exponent as i64;
    let fixed_fits = point <= WIDTH && point > -9;
    if fixed_fits {
        let places = if point >= WIDTH {
            0
        } else {
            WIDTH - point.max(1) - 1
        };
        let (whole, fraction) = digits(magnitude, places as i32);
        let fraction = fraction.trim_end_matches('0');
        let whole = if whole.is_empty() { "0".to_owned() } else { whole };
        if whole.len() as i64 <= WIDTH && (whole != "0" || !fraction.is_empty()) {
            let mut out = format!("{sign}{whole}");
            if !fraction.is_empty() {
                out.push_str(profile.decimal_separator);
                out.push_str(fraction);
            }
            return out;
        }
    }
    // Scientific: d.dddddE+xx, the mantissa's places filling what the exponent leaves.
    let mut exponent = point - 1;
    let exponent_width = if exponent.abs() >= 100 { 3 } else { 2 };
    let places = WIDTH - 2 - 2 - exponent_width;
    let (mantissa, carry) = significant(&first, places as usize + 1);
    exponent += carry;
    let (head, tail) = mantissa.split_at(1);
    let tail = tail.trim_end_matches('0');
    let mut out = format!("{sign}{head}");
    if !tail.is_empty() {
        out.push_str(profile.decimal_separator);
        out.push_str(tail);
    }
    out.push_str(&format!(
        "E{}{:02}",
        if exponent < 0 { '-' } else { '+' },
        exponent.abs()
    ));
    out
}

format::significant.text:
/// The first `count` significant digits of a non-zero decimal, rounded a half away from zero, and
/// 1 when the rounding carried into a new leading digit (the digits are then 1 and zeros).
fn significant(decimal: &ExactDecimal, count: usize) -> (String, i64) {
    let digits = decimal.coefficient.digits();
    if digits.len() <= count {
        return (format!("{digits}{}", "0".repeat(count - digits.len())), 0);
    }
    let dropped = (digits.len() - count) as i32;
    let rounded = decimal
        .round_at(decimal.exponent + dropped, Direction::Nearest)
        .expect("digits below the position");
    let out = rounded.coefficient.digits();
    if out.len() > count {
        (out[..count].to_owned(), 1)
    } else {
        (out, 0)
    }
}

format::sections.text:
/// The sections of a code, split at `;` outside quotes and escapes.
fn sections(code: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut current = String::new();
    let (mut quoted, mut escaped) = (false, false);
    for ch in code.chars() {
        if escaped {
            current.push(ch);
            escaped = false;
            continue;
        }
        match ch {
            '\\' => {
                current.push(ch);
                escaped = true;
            }
            '"' => {
                current.push(ch);
                quoted = !quoted;
            }
            ';' if !quoted => out.push(std::mem::take(&mut current)),
            _ => current.push(ch),
        }
    }
    out.push(current);
    out
}

format::bracket.text:
/// A bracketed token at the start of `text`: its inside and the rest.
fn bracket(text: &str) -> Option<(&str, &str)> {
    let rest = text.strip_prefix('[')?;
    let close = rest.find(']')?;
    Some((&rest[..close], &rest[close + 1..]))
}

format::is_elapsed.text:
fn is_elapsed(token: &str) -> bool {
    let lower = token.to_ascii_lowercase();
    !lower.is_empty()
        && lower.chars().all(|c| matches!(c, 'h' | 'm' | 's'))
        && lower.chars().all(|c| Some(c) == lower.chars().next())
}

format::condition_holds.text:
fn condition_holds(token: &str, value: f64) -> Option<bool> {
    let (op, rest) = ["<=", ">=", "<>", "<", ">", "="]
        .iter()
        .find_map(|op| token.strip_prefix(op).map(|rest| (*op, rest)))?;
    let threshold: f64 = rest.trim().parse().ok()?;
    Some(match op {
        "<" => value < threshold,
        "<=" => value <= threshold,
        ">" => value > threshold,
        ">=" => value >= threshold,
        "=" => value == threshold,
        _ => value != threshold,
    })
}

format::condition_of.text:
/// The leading condition of a section, if it has one.
fn condition_of(section: &str) -> Option<String> {
    let mut rest = section;
    while let Some((token, after)) = bracket(rest) {
        if is_condition(token) {
            return Some(token.to_owned());
        }
        rest = after;
    }
    None
}

format::strip_tokens.text:
/// A section with its bracketed tokens resolved: colors dropped, locale recorded for names, a currency tag
/// `[$sym-xxxx]` written as its symbol (quoted), conditions dropped, elapsed-time tokens kept.
fn strip_tokens(section: &str) -> Result<(String, Option<crate::locale::LocaleId>, bool), Failure> {
    let mut out = String::new();
    let mut name_locale = None;
    let mut locale_declared = false;
    let mut chars = section.chars().peekable();
    let (mut quoted, mut escaped) = (false, false);
    while let Some(ch) = chars.next() {
        if escaped {
            out.push(ch);
            escaped = false;
            continue;
        }
        match ch {
            '\\' => {
                out.push(ch);
                escaped = true;
            }
            '"' => {
                out.push(ch);
                quoted = !quoted;
            }
            '[' if !quoted => {
                let mut token = String::new();
                for next in chars.by_ref() {
                    if next == ']' {
                        break;
                    }
                    token.push(next);
                }
                if is_elapsed(&token) {
                    out.push('[');
                    out.push_str(&token);
                    out.push(']');
                } else if let Some(body) = token.strip_prefix('$') {
                    let (symbol, locale) = body.split_once('-').unwrap_or((body, ""));
                    if !locale.is_empty() {
                        locale_declared = true;
                        use crate::locale::LocaleId;
                        name_locale = u16::from_str_radix(locale, 16).ok()
                            .and_then(LocaleId::from_excel_lcid)
                            .or_else(|| LocaleId::from_bcp47_language_tag(locale));
                    }
                    if !symbol.is_empty() {
                        out.push('"');
                        out.push_str(symbol);
                        out.push('"');
                    }
                } else if is_condition(&token)
                    || token.chars().all(|c| c.is_ascii_alphanumeric())
                {
                    // A color ([Red], [Color10]) or a condition.
                } else {
                    return Err(Failure::NotModelled);
                }
            }
            _ => out.push(ch),
        }
    }
    Ok((out, name_locale, locale_declared))
}

format::choose.text:
/// The section a number is rendered with, and whether that section shows the number's sign
/// itself (so its magnitude is rendered).
fn choose(sections: &[String], value: f64) -> Result<(String, bool), Failure> {
    let numeric: Vec<&String> = sections.iter().take(3).collect();
    if numeric.iter().any(|s| condition_of(s).is_some()) {
        let mut fallback = None;
        for section in &numeric {
            match condition_of(section) {
                Some(token) => {
                    if condition_holds(&token, value).ok_or(Failure::NotModelled)? {
                        return Ok(((*section).clone(), false));
                    }
                }
                None => {
                    if fallback.is_none() {
                        fallback = Some((*section).clone());
                    }
                }
            }
        }
        return fallback.map(|s| (s, false)).ok_or(Failure::NotModelled);
    }
    Ok(match numeric.len() {
        1 => (numeric[0].clone(), false),
        2 => {
            if value < 0.0 {
                (numeric[1].clone(), true)
            } else {
                (numeric[0].clone(), false)
            }
        }
        _ => {
            if value > 0.0 {
                (numeric[0].clone(), false)
            } else if value < 0.0 {
                (numeric[1].clone(), true)
            } else {
                (numeric[2].clone(), false)
            }
        }
    })
}

format::items.text:
/// A section's items, with quoted text, escapes, `_x` (a space) and `*x` (nothing) resolved.
fn items(section: &str, profile: &FormatProfile) -> Result<Vec<Item>, Failure> {
    let decimal = profile.decimal_separator;
    let group = profile.thousands_separator;
    let chars: Vec<char> = section.chars().collect();
    let mut out = Vec::new();
    let mut at = 0;
    let literal = |out: &mut Vec<Item>, text: &str| {
        let text = currency_literal(profile, text);
        match out.last_mut() {
            Some(Item::Literal(existing)) => existing.push_str(text),
            _ => out.push(Item::Literal(text.to_owned())),
        }
    };
    while at < chars.len() {
        let ch = chars[at];
        let rest: String = chars[at..].iter().collect();
        match ch {
            '"' => {
                let close = chars[at + 1..]
                    .iter()
                    .position(|c| *c == '"')
                    .ok_or(Failure::NotModelled)?;
                let text: String = chars[at + 1..at + 1 + close].iter().collect();
                literal(&mut out, &text);
                at += close + 2;
            }
            '\\' => {
                let next = chars.get(at + 1).ok_or(Failure::NotModelled)?;
                let text = next.to_string();
                match out.last_mut() {
                    Some(Item::Literal(existing)) => existing.push_str(&text),
                    _ => out.push(Item::Literal(text)),
                }
                at += 2;
            }
            '_' => {
                literal(&mut out, " ");
                at += 2;
            }
            '*' => at += 2,
            '0' | '#' | '?' => {
                out.push(Item::Digit(ch));
                at += 1;
            }
            '%' => {
                out.push(Item::Percent);
                at += 1;
            }
            '@' => {
                out.push(Item::TextPlaceholder);
                at += 1;
            }
            'E' | 'e' if matches!(chars.get(at + 1), Some('+' | '-')) => {
                out.push(Item::Exponent(chars[at + 1] == '+'));
                at += 2;
            }
            _ if rest.starts_with(decimal) => {
                out.push(Item::Point);
                at += decimal.chars().count();
            }
            _ if !group.is_empty() && rest.starts_with(group) => {
                out.push(Item::Group);
                at += group.chars().count();
            }
            '/' => return Err(Failure::NotModelled),
            'E' if measured_host(profile) => return Err(Failure::Value),
            c if c.is_ascii_alphabetic() => {
                // A letter that is a token in some other format (dates, eras, A/P) is not modelled.
                if "ymdhsbegYMDHSBEG".contains(c)
                    || (matches!(c, 'a' | 'A') && !measured_host(profile)) {
                    return Err(Failure::NotModelled);
                }
                literal(&mut out, &c.to_string());
                at += 1;
            }
            c => {
                literal(&mut out, &c.to_string());
                at += 1;
            }
        }
    }
    Ok(out)
}

format::numeric.text:
/// Renders a number with a numeric section's items.
fn numeric(
    profile: &FormatProfile,
    value: f64,
    items: &[Item],
    show_minus: bool,
) -> Rendered {
    let first = items
        .iter()
        .position(|i| matches!(i, Item::Digit(_)))
        .ok_or(Failure::NotModelled)?;
    let last = items
        .iter()
        .rposition(|i| matches!(i, Item::Digit(_)))
        .expect("a digit placeholder");
    let exponent_at = items.iter().position(|i| matches!(i, Item::Exponent(_)));
    let mantissa_end = exponent_at.unwrap_or(last + 1);
    let point_at = items[..mantissa_end]
        .iter()
        .position(|i| *i == Item::Point);
    // Group separators right after the last mantissa placeholder divide by 1000 each.
    let mut scale_groups = 0;
    let mut cursor = items[..mantissa_end]
        .iter()
        .rposition(|i| matches!(i, Item::Digit(_)))
        .map(|p| p + 1)
        .unwrap_or(mantissa_end);
    while items.get(cursor) == Some(&Item::Group) {
        scale_groups += 1;
        cursor += 1;
    }
    let scale_end = cursor;
    let percents = items.iter().filter(|i| **i == Item::Percent).count() as i32;
    let mantissa_last = items[..mantissa_end]
        .iter()
        .rposition(|i| matches!(i, Item::Digit(_)))
        .unwrap_or(first);
    let integer_end = point_at.unwrap_or(mantissa_last + 1);
    // A group separator beside a literal in the integer part (dc-b1l, Excel 16.0.20430 on
    // 2026-10-25, the catalogue oracle's dcuar_text rows): one that follows a literal and precedes
    // a placeholder is written as the separator's text, a literal (TEXT(5415485.8,"##- 0") is
    // 541548- 6); one that follows a placeholder and precedes a literal is dropped and groups
    // nothing (TEXT(843124.584,"0# ,0") is 84312,5). One between two placeholders groups.
    let separator = Item::Literal(profile.thousands_separator.to_owned());
    let integer_items: Vec<Item> = items[first..integer_end.max(first)]
        .iter()
        .enumerate()
        .filter_map(|(at, item)| {
            let all = &items[first..integer_end.max(first)];
            if *item != Item::Group {
                return Some(item.clone());
            }
            let before = at.checked_sub(1).map(|p| &all[p]);
            let after = all.get(at + 1);
            match (before, after) {
                (Some(Item::Literal(_)), Some(Item::Digit(_))) => Some(separator.clone()),
                (Some(Item::Digit(_)), Some(Item::Literal(_))) => None,
                _ => Some(Item::Group),
            }
        })
        .collect();
    let integer: Vec<&Item> = integer_items.iter().collect();
    let mut fraction_literals: Vec<(usize, String)> = Vec::new();
    let fraction: Vec<char> = match point_at {
        Some(p) => {
            let mut places = Vec::new();
            for item in &items[p + 1..mantissa_end] {
                match item {
                    Item::Digit(c) => places.push(*c),
                    Item::Group => {}
                    Item::Literal(text) => fraction_literals.push((places.len(), text.clone())),
                    _ => return Err(Failure::NotModelled),
                }
            }
            places
        }
        None => Vec::new(),
    };
    // A literal among the decimal places stands after as many of them as precede it in the code
    // (Excel 16.0.20430, dc-uar: TEXT(1234567.891,"# ##0.0,0") is 1 234 567.8,9); modelled for
    // `0` places only.
    if !fraction_literals.is_empty() && fraction.iter().any(|c| *c != '0') {
        return Err(Failure::NotModelled);
    }
    let grouping = integer
        .iter()
        .enumerate()
        .any(|(at, i)| **i == Item::Group && integer[at + 1..].iter().any(|j| matches!(j, Item::Digit(_))));
    let prefix: String = items[..first]
        .iter()
        .map(|i| literal_text(i, profile))
        .collect::<Result<String, Failure>>()?;
    let suffix_from = match exponent_at {
        Some(_) => last + 1,
        None => scale_end.max(last + 1),
    };
    let suffix: String = items[suffix_from..]
        .iter()
        .map(|i| literal_text(i, profile))
        .collect::<Result<String, Failure>>()?;

    let mut scaled = value.abs() * 100f64.powi(percents);
    if scale_groups > 0 {
        scaled /= 1000f64.powi(scale_groups);
    }
    let places = fraction.len() as i32;

    let (body, nonzero) = match exponent_at {
        Some(e) => scientific(profile, scaled, &integer, &fraction, items, e)?,
        None => {
            let (whole, frac) = digits(scaled, places);
            let nonzero = whole.chars().chain(frac.chars()).any(|c| c != '0');
            let whole_text = integer_part(profile, &whole, &integer, grouping)?;
            let mut frac_text = fraction_part(&frac, &fraction);
            for (after, text) in fraction_literals.iter().rev() {
                frac_text.insert_str((*after).min(frac_text.len()), text);
            }
            let mut body = whole_text;
            if point_at.is_some() {
                body.push_str(profile.decimal_separator);
                body.push_str(&frac_text);
            }
            (body, nonzero)
        }
    };
    let minus = if show_minus && value < 0.0 && nonzero {
        "-"
    } else {
        ""
    };
    Ok(format!("{minus}{prefix}{body}{suffix}"))
}

format::literal_text.text:
fn literal_text(item: &Item, profile: &FormatProfile) -> Result<String, Failure> {
    Ok(match item {
        Item::Literal(text) => text.clone(),
        Item::Percent => "%".to_owned(),
        Item::Group => profile.thousands_separator.to_owned(),
        Item::Point => profile.decimal_separator.to_owned(),
        Item::Digit(_) | Item::Exponent(_) | Item::TextPlaceholder => return Err(Failure::NotModelled),
    })
}

format::integer_part.text:
/// The integer part: digits fill the placeholders from the right, the leftmost placeholder takes
/// any digits left over, `0` writes a zero and `?` a space where no digit is left, literals stay
/// where they stand, and grouping writes the locale's group separator between groups of three.
fn integer_part(
    profile: &FormatProfile,
    whole: &str,
    pattern: &[&Item],
    grouping: bool,
) -> Result<String, Failure> {
    let placeholders: Vec<char> = pattern
        .iter()
        .filter_map(|i| match i {
            Item::Digit(c) => Some(*c),
            _ => None,
        })
        .collect();
    if grouping {
        // A literal among grouped placeholders stands where as many digits are to its right as
        // there are placeholders to its right in the code, the grouping counted on the digits
        // alone (Excel 16.0.20430, dc-uar: TEXT(1234567.891,"# ##0,0") is 1 234 56,8, and
        // TEXT(12,"#-# ##0") is -12). Modelled for `0` and `#` placeholders and literals that do
        // not fall beside a group separator.
        // A group separator beside a literal that the caller did not resolve (one between two
        // literals, or at either end) is not modelled.
        let beside_literal = pattern.iter().enumerate().any(|(at, item)| {
            **item == Item::Group
                && (at == 0
                    || !matches!(pattern[at - 1], Item::Digit(_))
                    || !matches!(pattern.get(at + 1), Some(Item::Digit(_))))
        });
        if beside_literal && pattern.iter().any(|i| matches!(i, Item::Literal(_))) {
            return Err(Failure::NotModelled);
        }
        let mut literals: Vec<(usize, String)> = Vec::new();
        let mut right = 0;
        for item in pattern.iter().rev() {
            match item {
                Item::Digit('?') => return Err(Failure::NotModelled),
                Item::Digit(_) => right += 1,
                Item::Group => {}
                other => {
                    // Literals with no placeholder between them stand together, in the code's
                    // order (dc-b1l: TEXT(503134,"0- 0 #") is 503 1- 34).
                    let text = literal_text(other, profile)?;
                    match literals.last_mut() {
                        Some((count, joined)) if *count == right => joined.insert_str(0, &text),
                        _ => literals.push((right, text)),
                    }
                }
            }
        }
        let zeros = placeholders
            .iter()
            .rev()
            .take_while(|_| true)
            .enumerate()
            .filter(|(_, c)| **c == '0')
            .map(|(at, _)| at + 1)
            .max()
            .unwrap_or(0);
        let mut digits = whole.to_owned();
        while digits.len() < zeros {
            digits.insert(0, '0');
        }
        let mut text = grouped(&digits, profile.thousands_separator);
        // Literals nearest the right first; each goes left of its digits.
        for (count, literal) in &literals {
            let mut seen = 0;
            let mut at = text.len();
            if *count > 0 {
                at = 0;
                for (index, c) in text.char_indices().rev() {
                    if c.is_ascii_digit() {
                        seen += 1;
                        if seen == *count {
                            at = index;
                            break;
                        }
                    }
                }
                // A literal where a group separator falls stands after it (dc-b1l:
                // TEXT(9514218,"0x#0# ###") is 9 x514 218).
                if seen < *count {
                    at = 0;
                }
            }
            text.insert_str(at, literal);
        }
        return Ok(text);
    }
    let chars: Vec<char> = whole.chars().collect();
    let mut next = chars.len();
    let mut out: Vec<String> = Vec::new();
    let leftmost = pattern
        .iter()
        .position(|i| matches!(i, Item::Digit(_)))
        .unwrap_or(0);
    for (at, item) in pattern.iter().enumerate().rev() {
        match item {
            Item::Digit(c) => {
                let mut piece = String::new();
                if next > 0 {
                    next -= 1;
                    piece.push(chars[next]);
                    if at == leftmost && next > 0 {
                        let rest: String = chars[..next].iter().collect();
                        piece.insert_str(0, &rest);
                        next = 0;
                    }
                } else if *c == '0' {
                    piece.push('0');
                } else if *c == '?' {
                    piece.push(' ');
                }
                out.push(piece);
            }
            other => out.push(literal_text(other, profile)?),
        }
    }
    out.reverse();
    Ok(out.concat())
}

format::fraction_part.text:
/// The decimal places: `0` writes its digit, `#` drops a trailing zero, `?` writes a trailing
/// zero as a space.
fn fraction_part(digits: &str, pattern: &[char]) -> String {
    let chars: Vec<char> = digits.chars().collect();
    let mut out: Vec<char> = chars.clone();
    for at in (0..chars.len()).rev() {
        if chars[at] != '0' {
            break;
        }
        match pattern[at] {
            '#' => {
                out.pop();
            }
            '?' => out[at] = ' ',
            _ => break,
        }
    }
    out.into_iter().collect()
}

format::scientific.text:
/// A scientific mantissa and exponent.
fn scientific(
    profile: &FormatProfile,
    value: f64,
    integer: &[&Item],
    fraction: &[char],
    items: &[Item],
    exponent_at: usize,
) -> Result<(String, bool), Failure> {
    let Item::Exponent(plus) = items[exponent_at] else {
        unreachable!()
    };
    let exponent_digits: Vec<char> = items[exponent_at + 1..]
        .iter()
        .take_while(|i| matches!(i, Item::Digit(_)))
        .map(|i| match i {
            Item::Digit(c) => *c,
            _ => unreachable!(),
        })
        .collect();
    if exponent_digits.is_empty() {
        return Err(Failure::NotModelled);
    }
    let whole_places: Vec<char> = integer
        .iter()
        .filter_map(|i| match i {
            Item::Digit(c) => Some(*c),
            Item::Group => None,
            _ => Some('!'),
        })
        .collect();
    if whole_places.contains(&'!') || whole_places.is_empty() {
        return Err(Failure::NotModelled);
    }
    let width = whole_places.len() as i64;
    let engineering = width > 1 && whole_places[0] == '#';
    if value == 0.0 {
        let mantissa = format!(
            "0{}{}",
            if fraction.is_empty() { "" } else { profile.decimal_separator },
            "0".repeat(fraction.len())
        );
        let exponent = format!("E{}{}", if plus { "+" } else { "" }, "0".repeat(exponent_digits.len()));
        return Ok((format!("{mantissa}{exponent}"), false));
    }
    let first = fifteen(value);
    let length = first.coefficient.digits().len() as i64;
    let point = length + first.exponent as i64; // value = 0.d * 10^point
    let leading = if engineering {
        // The exponent is a multiple of the width.
        let e = (point - 1).div_euclid(width) * width;
        point - e
    } else {
        width.min(point.max(1)).max(1)
    };
    let mut exponent = point - leading;
    let count = (leading + fraction.len() as i64) as usize;
    let (mut mantissa_digits, carry) = significant(&first, count);
    if carry == 1 {
        exponent += 1;
        if engineering && exponent.rem_euclid(width) != 0 {
            // A carry past the width moves to the next multiple.
            mantissa_digits.push('0');
        }
    }
    let lead = leading as usize;
    let (whole, frac) = mantissa_digits.split_at(lead.min(mantissa_digits.len()));
    let frac = fraction_part(&frac[..fraction.len().min(frac.len())], fraction);
    let mut out = whole.to_owned();
    if !fraction.is_empty() {
        out.push_str(profile.decimal_separator);
        out.push_str(&frac);
    }
    let sign = if exponent < 0 {
        "-"
    } else if plus {
        "+"
    } else {
        ""
    };
    out.push_str(&format!(
        "E{sign}{:0width$}",
        exponent.abs(),
        width = exponent_digits.len()
    ));
    Ok((out, true))
}

format::fraction_code.text:
fn fraction_code(section: &str) -> Option<FractionCode> {
    let (top, bottom) = section.split_once('/')?;
    let placeholders = |s: &str| !s.is_empty() && s.chars().all(|c| matches!(c, '0' | '#' | '?'));
    if !placeholders(top) {
        return None;
    }
    let denominator = if placeholders(bottom) {
        let chars: Vec<char> = bottom.chars().collect();
        if chars.contains(&'0') && chars.iter().any(|c| *c != '0') {
            return None;
        }
        Err(chars)
    } else if !bottom.is_empty()
        && bottom.len() <= 9
        && bottom.chars().all(|c| c.is_ascii_digit())
        && !bottom.starts_with('0')
    {
        Ok(bottom.parse().ok()?)
    } else {
        return None;
    };
    let numerator: Vec<char> = top.chars().collect();
    if numerator.contains(&'0') && numerator.iter().any(|c| *c != '0') {
        return None;
    }
    Some(FractionCode {
        numerator,
        denominator,
    })
}

format::FractionCode::render.text:
fn render(&self, value: f64, show_minus: bool) -> Rendered {
    let x = value.abs();
    let (numerator, denominator) = match &self.denominator {
        Ok(d) => {
            let n = (x * *d as f64 + 0.5).floor();
            if !(n <= 32767.0) {
                return Err(Failure::Value);
            }
            (n as u64, *d)
        }
        Err(places) => {
            let largest = 10u64.pow(places.len() as u32) - 1;
            convergent(x, largest).ok_or(Failure::NotModelled)?
        }
    };
    let mut out = String::new();
    if show_minus && value < 0.0 && numerator != 0 {
        out.push('-');
    }
    let top = numerator.to_string();
    let missing = self.numerator.len().saturating_sub(top.len());
    for c in &self.numerator[..missing] {
        match c {
            '0' => out.push('0'),
            '?' => out.push(' '),
            _ => {}
        }
    }
    out.push_str(&top);
    out.push('/');
    let bottom = denominator.to_string();
    match &self.denominator {
        Ok(_) => out.push_str(&bottom),
        Err(places) => {
            let missing = places.len().saturating_sub(bottom.len());
            if places.first() == Some(&'0') {
                out.push_str(&"0".repeat(missing));
                out.push_str(&bottom);
            } else {
                out.push_str(&bottom);
                for c in &places[places.len() - missing..] {
                    if *c == '?' {
                        out.push(' ');
                    }
                }
            }
        }
    }
    Ok(out)
}

format::mixed_fraction_under_space_group.text:
/// Whether `section` is a fraction with an integer part set off by the group separator, under a
/// locale whose group separator is a space: Excel 16.0.20430 under en-ZA gave #VALUE! for every
/// such code it was given (`# ?/?`, `# ??/??`, `# ???/???`, `# ?/8`, `# ?/100`, `0 ?/?`,
/// `#,##0 ?/?`; dc-uar, the catalogue oracle's sheet dcuar_text).
fn mixed_fraction_under_space_grouping(section: &str, profile: &FormatProfile) -> bool {
    if profile.thousands_separator != " " {
        return false;
    }
    let Some((whole, fraction)) = section.rsplit_once(' ') else {
        return false;
    };
    let placeholders = |s: &str| !s.is_empty() && s.chars().all(|c| matches!(c, '0' | '#' | '?'));
    whole.chars().any(|c| matches!(c, '0' | '#'))
        && whole.chars().all(|c| matches!(c, '0' | '#' | '?' | ','))
        && fraction_code(fraction).is_some()
        && fraction.split_once('/').is_some_and(|(top, _)| placeholders(top))
}

format::convergent.text:
/// The last convergent of `x`'s continued fraction, computed in binary64, whose denominator is
/// at most `largest`.
fn convergent(x: f64, largest: u64) -> Option<(u64, u64)> {
    let (mut h0, mut h1, mut k0, mut k1) = (0f64, 1f64, 1f64, 0f64);
    let mut best = None;
    let mut y = x;
    for _ in 0..64 {
        let a = y.floor();
        let (h2, k2) = (a * h1 + h0, a * k1 + k0);
        if k2 > largest as f64 || !h2.is_finite() || h2 >= 1e15 {
            break;
        }
        (h0, h1, k0, k1) = (h1, h2, k1, k2);
        best = Some((h1 as u64, k1 as u64));
        let rest = y - a;
        if rest == 0.0 {
            break;
        }
        y = 1.0 / rest;
    }
    best
}

format::text_declared_date_locale.text:
/// A declared date-name locale supplies all profile fields used by these date-only
/// sections. Host separators and designators remain unavailable; admit only fields
/// that never read them, then use the same formatter with the locale the code names.
pub(crate) fn text_declared_date_locale(system: DateSystem, value: f64, code: &str) -> Rendered {
    let sections = sections(code);
    if sections.iter().any(|section| condition_of(section).is_some()) {
        return Err(Failure::NotModelled);
    }
    let (section, _) = choose(&sections, value).map_err(|_| Failure::NotModelled)?;
    let (stripped, name_locale, _) = strip_tokens(&section).map_err(|_| Failure::NotModelled)?;
    let locale = name_locale.ok_or(Failure::NotModelled)?;
    if stripped.trim().is_empty() || !stripped.chars().all(|c| matches!(c,
        'y' | 'Y' | 'm' | 'M' | 'd' | 'D' | 'g' | 'G' | 'e' | 'E' | ' ')) {
        return Err(Failure::NotModelled);
    }
    text(&crate::locale::format_profile(locale), system, value, code)
}

format::text.text:
/// TEXT of a number under `code`.
pub(crate) fn text(profile: &FormatProfile, system: DateSystem, value: f64, code: &str) -> Rendered {
    if !value.is_finite() {
        return Err(Failure::Value);
    }
    let sections = sections(code);
    let (section, signed_section) = choose(&sections, value)?;
    let (stripped, name_locale, locale_declared) = strip_tokens(&section)?;
    if stripped.trim().eq_ignore_ascii_case("general") {
        let shown = general(profile, if signed_section { value.abs() } else { value });
        return Ok(shown);
    }
    let magnitude_only = signed_section;
    if !locale_declared && measured_host(profile) && datetime::has_invalid_exponent(&stripped) {
        return Err(Failure::Value);
    }
    if datetime::looks_like_datetime_format(&stripped) {
        if value < 0.0 {
            return Err(Failure::Value);
        }
        if value >= 2_958_466.0 {
            return Err(Failure::Value);
        }
        if datetime::without_subseconds(&stripped)
            .chars()
            .any(|c| matches!(c, 'b' | 'B' | '0') ||
                (matches!(c, 'e' | 'g' | 'G') && name_locale != Some(crate::locale::LocaleId::JaJp)
                    && !(!locale_declared && measured_host(profile))))
        {
            return Err(Failure::NotModelled);
        }
        return datetime::render_with_datetime_tokens(profile, system, value, &stripped, name_locale, !locale_declared)
            .ok_or(Failure::NotModelled);
    }
    if let Some(fraction) = fraction_code(&stripped) {
        return fraction.render(value, !magnitude_only);
    }
    if mixed_fraction_under_space_grouping(&stripped, profile) {
        return Err(Failure::Value);
    }
    let mut items = items(&stripped, profile)?;
    if !items.iter().any(|i| matches!(i, Item::Digit(_))) {
        // Fn8 literal-only controls: a run of ordinary-space grouping tokens
        // writes one space. Numeric grouping and trailing scaling stay below.
        if measured_host(profile) && profile.thousands_separator == " " {
            items.dedup_by(|a, b| *a == Item::Group && *b == Item::Group);
            for item in &mut items {
                if *item == Item::Group { *item = Item::Literal(" ".to_owned()); }
            }
        }
        // A section of literals alone writes them (an empty one writes nothing).
        if items.iter().any(|i| matches!(i, Item::Point | Item::Group | Item::Exponent(_))) {
            return Err(Failure::NotModelled);
        }
        if items.iter().any(|i| matches!(i, Item::TextPlaceholder)) {
            // Fn4 qt001..qt030: active @ and @! select General for numbers,
            // including values whose full numeric text has different precision.
            return Ok(general(profile, if signed_section { value.abs() } else { value }));
        }
        let literal = items
            .iter()
            .map(|i| literal_text(i, profile))
            .collect::<Result<String, Failure>>()?;
        // Keep the ordinary automatic sign when section selection has not
        // suppressed it, even for quoted text (fn4 qt008). Empty stays empty.
        return Ok(if value < 0.0 && !signed_section && !literal.is_empty() {
            format!("-{literal}")
        } else {
            literal
        });
    }
    if items.iter().any(|i| matches!(i, Item::TextPlaceholder)) {
        return Err(Failure::NotModelled);
    }
    numeric(profile, value, &items, !magnitude_only)
}

format::text_of_text.text:
/// TEXT of a text value under `code`: the fourth section, or a first section holding `@`, with
/// `@` written as the text; otherwise the text as it is.
pub(crate) fn text_of_text(text: &str, code: &str, profile: &FormatProfile) -> Rendered {
    let sections = sections(code);
    let section = match sections.get(3) {
        Some(section) => section.clone(),
        None if sections.len() == 1 && sections[0].contains('@') => sections[0].clone(),
        None => return Ok(text.to_owned()),
    };
    let (stripped, _, _) = strip_tokens(&section)?;
    let mut out = String::new();
    for part in stripped.split('@').enumerate() {
        if part.0 > 0 {
            out.push_str(text);
        }
        let items = items(part.1, profile)?;
        for item in &items {
            out.push_str(&literal_text(item, profile)?);
        }
    }
    Ok(out)
}

format/names::month_name.text:
pub(crate) fn month_name(profile: &FormatProfile, month: i64, abbreviated: bool, tagged: bool) -> String {
    let Ok(index) = usize::try_from(month - 1) else {
        return String::new();
    };
    // Fn1 and fn3 measure names under explicit format tags. These tagged forms
    // differ from the locale data's ordinary abbreviations.
    if tagged && profile.id == LocaleId::DeDe && month == 3 && abbreviated {
        return "Mrz".to_owned();
    }
    let names = locale_names(profile.id);
    if tagged && abbreviated {
        match profile.id {
            LocaleId::JaJp => return names.months_short.get(index)
                .map(|_| month.to_string()).unwrap_or_default(),
            LocaleId::RuRu => return names.months_long.get(index).copied().unwrap_or("")
                .chars().take(3).collect(),
            _ => {}
        }
    }
    let name = if abbreviated {
        names.months_short.get(index).copied().unwrap_or("")
    } else {
        names.months_long.get(index).copied().unwrap_or("")
    };
    if tagged && profile.id == LocaleId::RuRu {
        let mut chars = name.chars();
        chars.next().map(|first| first.to_uppercase().chain(chars).collect()).unwrap_or_default()
    } else {
        name.to_owned()
    }
}

