coerce::number.text:
/// The value as a number: a number as it is, TRUE as 1 and FALSE as 0, Empty and Missing as 0,
/// text through [`text_as_decimal`], an error as itself. An array (whose operator lifts over its
/// elements) and a reference are not read here.
pub(crate) fn number(value: &CalcValue) -> Result<Numeric, Stop> {
    if value.is_excel_overflow() {
        return Err(Stop::Error(WorksheetErrorCode::Num));
    }
    match value.core_ref() {
        CoreRef::Number(n) => operand(n).map(Numeric::Number),
        CoreRef::Logical(b) => Ok(Numeric::Number(if b { 1.0 } else { 0.0 })),
        CoreRef::Text(text) => text_as_decimal(text).map(Numeric::Decimal),
        CoreRef::Empty | CoreRef::Missing => Ok(Numeric::Number(0.0)),
        CoreRef::Error(code) => Err(Stop::Error(code)),
        CoreRef::Array(_) | CoreRef::Reference(_) => Err(Stop::NotModelled),
    }
}

catalogue/text_format::width_conversion.text:
/// ASC and DBCS change character widths only under a double-byte language; under every other
/// profile Excel gives the text as it is (Excel 16.0.20527 under en-ZA, the catalogue's sheet
/// dczsn3_bytes: full-width and half-width forms, kana, CJK and Hangul are kept). Under the
/// ja-JP, ko-KR and zh-CN profiles they are refused (bead dc-zsn.3).
fn width_conversion(site: &Site<'_>, a: &[CalcValue]) -> Step<CalcValue> {
    let (_, profile) = profile(site)?;
    if matches!(
        profile.id,
        LocaleId::JaJp | LocaleId::KoKr | LocaleId::ZhCn
    ) {
        return Err(site.not_modelled(None));
    }
    Ok(CalcValue::text(text_arg(site, a, 0)?))
}

ported/asinh::asinh_kernel.text:
pub fn asinh_kernel(n: f64) -> Result<f64, WorksheetErrorCode> {
    // Excel computes `ln(x + sqrt(x² + 1))` and overflows when the `x²` intermediate
    // overflows f64, publishing `#NUM!` rather than the (finite, representable) analytic
    // value for such large |x|. Reproduce that boundary *bit-exactly* by forming the same
    // `x*x` intermediate Excel forms and rejecting when it is non-finite: this flips to
    // `#NUM!` at exactly the input Excel does (|x| > sqrt(f64::MAX) = 1.3407807929942596e154,
    // verified live against Excel 16.0 build 20026 around 0x5fefffffffffffff↔0x5ff0000000000000).
    // No guessed magic constant — identical f64 arithmetic yields Excel's exact threshold.
    if !(n * n).is_finite() {
        return Err(WorksheetErrorCode::Num);
    }
    // Inverse-problem identity, live Excel 16.0 b20228 Range.Value2:
    // ASINH(x) == SIGN(x)*LN(ABS(x)+SQRT(x*x+1)) on 23/23 signed rows.
    // The unsigned LN(x+SQRT(x*x+1)) misses negatives. Worksheet HYPOT
    // is not the graph. When x*x+1 overflows (x*x == f64::MAX), SQRT
    // cannot be formed; the published finite value is LN(2*|x|).
    let a = n.abs();
    // The recorded identity stores each operation from PC64, including SQRT.
    // Retaining the entire expression in the registers loses recorded matches.
    let sq = excel_x87_mul(a, a);
    let radicand = excel_x87_add(sq, 1.0);
    let inner = if !radicand.is_finite() {
        excel_x87_add(a, a)
    } else {
        excel_x87_add(a, excel_sqrt_staged(radicand))
    };
    Ok(n.signum() * crate::ported::excel_numeric::excel_log(inner))
}

catalogue/kit::num_with_subnormal.text:
/// Number coercion for a kernel that implements its own measured subnormal input policy.
/// Keep the ordinary coercions and refusals for every other kind of value.
pub(super) fn num_with_subnormal(
    site: &Site<'_>,
    arguments: &[CalcValue],
    index: usize,
) -> Step<f64> {
    match arguments[index].core_ref() {
        CoreRef::Number(n) if n.is_subnormal() => Ok(n),
        _ => num(site, arguments, index),
    }
}

