/// A one-argument kernel whose raw result Excel publishes under `policy`.
fn raw(site: &Site<'_>, a: &[CalcValue], policy: ExcelRealPolicy, kernel: fn(f64) -> f64) -> Step<CalcValue> {
    let x = num(site, a, 0)?;
    out(site, policy.publish(x, kernel(x)))
}

