ported/atan2::atan2_kernel.text:
pub fn atan2_kernel(x_num: f64, y_num: f64) -> Result<f64, WorksheetErrorCode> {
    if x_num == 0.0 && y_num == 0.0 {
        return Err(WorksheetErrorCode::Div0);
    }
    // Excel returns #NUM! when the implicit y/x ratio overflows to infinity
    // (x != 0 and |y| >> |x|), e.g. ATAN2(1e-200, 1e109). A finite ratio stays a
    // number, and the axis case x == 0 (ratio undefined, not overflowing) keeps
    // its ±pi/2 value. Pinned against live Excel 16.0 b20026 (BUG-FUNC-027 B3).
    if x_num != 0.0 && (y_num / x_num).is_infinite() {
        return Err(WorksheetErrorCode::Num);
    }
    // Excel's angle is the arctangent of the binary64 ratio y/x, moved by pi into the left
    // half-plane (dc-j9k: 15 of 15 sweep readings and the catalogue oracle's ATAN2 rows of sheet
    // dcj9k_math; the correctly rounded atan2 matched 10 of 15). On the y axis it is ±pi/2.
    if x_num == 0.0 {
        return Ok(std::f64::consts::FRAC_PI_2.copysign(y_num));
    }
    let angle = crate::ported::excel_numeric::excel_atan(y_num / x_num);
    Ok(if x_num > 0.0 {
        angle
    } else if y_num >= 0.0 {
        angle + std::f64::consts::PI
    } else {
        angle - std::f64::consts::PI
    })
}

ported/excel_numeric::excel_atan.text:
/// Direct public FPATAN operation retained for separately characterized callers
/// and research comparisons. W111's ATAN and revised imaginary-family callers
/// use the magnitude-reduced graph below.
pub(crate) fn excel_atan(x: f64) -> f64 {
    #[cfg(all(target_arch = "x86_64", not(feature = "soft-x87")))]
    {
        x87::atan(x)
    }
    #[cfg(not(all(target_arch = "x86_64", not(feature = "soft-x87"))))]
    {
        atan_with::<Soft>(x)
    }
}

ported/atanh::atanh_kernel.text:
pub fn atanh_kernel(n: f64) -> Result<f64, WorksheetErrorCode> {
    let a = n.abs();
    if a >= 1.0 {
        return Err(WorksheetErrorCode::Num);
    }
    // Current-reference Excel observes DAZ inputs in this legacy body. Both
    // signs of every subnormal input publish positive zero.
    if a < f64::MIN_POSITIVE {
        return Ok(0.0);
    }
    // W109 G4-02 (build 20228/CV2, NoCache): the old apparent x87-ln1p pair
    // was observationally equivalent only on the sparse small-input corpus.
    // Dense disagreement mapping identifies the actual body as the ordinary
    // binary64 cubic `x + x^3/3`, up to the exact threshold above.
    if a < ATANH_RATIO_FLOOR {
        return Ok(n + (n * n * n) / 3.0);
    }

    // The ratio body is a legacy x87 spill unit: each wrapper operation is
    // RN53(RN64(op)) before the established x87 LN publication. All three
    // add/sub/div stores are independently required by the fresh wrapper-mask
    // held-out. The signed ratio is evaluated directly, so this region is not
    // globally odd.
    let numerator = crate::ported::excel_numeric::excel_x87_add(1.0, n);
    let denominator = crate::ported::excel_numeric::excel_x87_sub(1.0, n);
    let ratio = crate::ported::excel_numeric::excel_x87_div(numerator, denominator);
    Ok(0.5 * crate::ported::excel_numeric::excel_log(ratio))
}

catalogue/statistics::all.text:
/// Every argument's numbers by the aggregate rule `held`.
fn all(site: &Site<'_>, a: &[CalcValue], sv: &mut EvalServices<'_>, held: Held) -> Step<Vec<f64>> {
    numbers(site, a, 0, a.len(), sv, held)
}

catalogue/statistics::entry::AVEDEV.text:
1 avedev "AVEDEV" (1, 255) [R "number1", R "number2"] |s, a, sv| {
    let values = all(s, a, sv, Held::Numbers)?;
    if values.is_empty() {
        return fail(WorksheetErrorCode::Num);
    }
    let mean = values.iter().sum::<f64>() / values.len() as f64;
    let avedev = values.iter().map(|v| (v - mean).abs()).sum::<f64>() / values.len() as f64;
    s.number(avedev)
}

catalogue/kit::numbers.text:
/// The numbers the arguments `from..` give an aggregate that reads held values by `held`, in the
/// reading order: a direct argument through number coercion, a held value as the aggregate rule
/// says (see the aggregate family). The first error is the result.
pub(super) fn numbers(
    site: &Site<'_>,
    arguments: &[CalcValue],
    from: usize,
    to: usize,
    services: &mut EvalServices<'_>,
    held: Held,
) -> Step<Vec<f64>> {
    let mut found = Vec::new();
    aggregate::each_number(site, &arguments[from..to], services, held, &mut |n| {
        found.push(n);
        Ok(())
    })?;
    Ok(found)
}

