fn total(site: &Site<'_>, plan: &Plan, services: &mut EvalServices<'_>) -> Step<CalcValue> {
    let mut total = 0.0;
    plan.each_matched(site, services, &mut |n| {
        total = site.add(total, n)?;
        Ok(())
    })?;
    site.number(total)
}

