fn bessel(site: &Site<'_>, a: &[CalcValue], kernel: fn(f64, f64) -> Result<f64, WorksheetErrorCode>, checked_kinds: bool) -> Step<CalcValue> {
    if checked_kinds { radix_kind(a, 0)?; }
    let x = num(site, a, 0)?;
    if checked_kinds { radix_kind(a, 1)?; }
    let n = num(site, a, 1)?;
    out(site, kernel(x, n))
}

