fn polynomial_with(
    x: f64,
    coefficients: &[f64],
    multiply: impl Fn(f64, f64) -> f64,
    add: impl Fn(f64, f64) -> f64,
) -> f64 {
    let mut value = *coefficients.last().unwrap();
    for &coefficient in coefficients[..coefficients.len() - 1].iter().rev() {
        value = add(multiply(x, value), coefficient);
    }
    value
}

