/// grat1: evaluation of (P(a,x), Q(a,x)) for a <= 1.
fn bratio_grat1(a: f64, x: f64, r: f64, eps: f64) -> (f64, f64) {
    if a * x == 0.0 {
        if x <= a {
            return (0.0, 1.0);
        }
        return (1.0, 0.0);
    }
    if a == 0.5 {
        if x < 0.25 {
            let p = bratio_erf_nswc(x.sqrt());
            return (p, 0.5 + (0.5 - p));
        }
        let q = bratio_erfc1(0, x.sqrt());
        return (0.5 + (0.5 - q), q);
    }
    if x < 1.1 {
        let mut an = 3.0;
        let mut c = x;
        let mut summ = x / (a + 3.0);
        let tol = 0.1 * eps / (a + 1.0);
        loop {
            an += 1.0;
            c = -c * (x / an);
            let t = c / (a + an);
            summ += t;
            if t.abs() <= tol {
                break;
            }
        }
        let j = a * x * ((summ / 6.0 - 0.5 / (a + 2.0)) * x + 1.0 / (a + 1.0));
        let z = a * crt_log(x);
        let h = bratio_gam1(a);
        let g = 1.0 + h;
        let go50 = if x < 0.25 { z > -0.13394 } else { a < x / 2.59 };
        if go50 {
            let l = bratio_rexp(z);
            let w = 0.5 + (0.5 + l);
            let q = (w * j - l) * g - h;
            if q < 0.0 {
                return (1.0, 0.0);
            }
            return (0.5 + (0.5 - q), q);
        }
        let w = crate::ported::excel_numeric::excel_exp(z);
        let p = w * g * (0.5 + (0.5 - j));
        return (p, 0.5 + (0.5 - p));
    }
    // continued fraction
    let mut a2nm1 = 1.0;
    let mut a2n = 1.0;
    let mut b2nm1 = x;
    let mut b2n = x + (1.0 - a);
    let mut c = 1.0;
    let mut an0;
    loop {
        a2nm1 = x * a2n + c * a2nm1;
        b2nm1 = crate::ported::excel_numeric::excel_x87_mul_add(x, b2n, c * b2nm1);
        let am0 = a2nm1 / b2nm1;
        c += 1.0;
        let cma = c - a;
        a2n = a2nm1 + cma * a2n;
        b2n = b2nm1 + cma * b2n;
        an0 = a2n / b2n;
        if (an0 - am0).abs() < eps * an0 {
            break;
        }
    }
    let q = r * an0;
    (0.5 + (0.5 - q), q)
}

