}

ported/ceiling_floor_family::normalize_z.text:
fn normalize_zero(x: f64) -> f64 {
    if x == 0.0 { 0.0 } else { x }
}

ported/ceiling_floor_family::ceiling_mat.text:
pub fn ceiling_math_kernel(
    number: f64,
    significance: f64,
    mode: f64,
) -> Result<f64, WorksheetErrorCode> {
    let significance = significance.abs();
    if significance == 0.0 {
        return Ok(0.0);
    }
    let result = if number >= 0.0 {
        significance * excel_quotient(number, significance).ceil()
    } else if mode != 0.0 {
        -significance * excel_quotient(-number, significance).ceil()
    } else {
        -significance * excel_quotient(-number, significance).floor()
    };
    Ok(normalize_zero(result))
}

catalogue/kit::opt.text:
/// Argument `index` as a number, or `default` when the call does not reach it. An argument the
/// call leaves empty (`f(1,)`) is read as 0, as coercion reads it.
pub(super) fn opt(
    site: &Site<'_>,
    arguments: &[CalcValue],
    index: usize,
    default: f64,
) -> Step<f64> {
    if index < arguments.len() {
        num(site, arguments, index)
    } else {
        Ok(default)
    }
}

