ported/paired_stats_common::means.text:
fn means(pairs: &[(f64, f64)]) -> Result<(f64, f64), WorksheetErrorCode> {
    if pairs.is_empty() {
        return Err(WorksheetErrorCode::Div0);
    }
    let (sum_x, sum_y) = pairs
        .iter()
        .fold((0.0, 0.0), |(ax, ay), (x, y)| (ax + x, ay + y));
    let n = pairs.len() as f64;
    Ok((sum_x / n, sum_y / n))
}

ported/paired_stats_common::correlation_.text:
pub fn correlation_from_pairs(pairs: &[(f64, f64)]) -> Result<f64, WorksheetErrorCode> {
    if pairs.len() < 2 {
        return Err(WorksheetErrorCode::Div0);
    }
    let (mean_x, mean_y) = means(pairs)?;
    let mut sum_xy = 0.0;
    let mut sum_x2 = 0.0;
    let mut sum_y2 = 0.0;
    for (x, y) in pairs {
        let dx = *x - mean_x;
        let dy = *y - mean_y;
        sum_xy += dx * dy;
        sum_x2 += dx * dx;
        sum_y2 += dy * dy;
    }
    if sum_x2 == 0.0 || sum_y2 == 0.0 {
        return Err(WorksheetErrorCode::Div0);
    }
    let denom = (pairs.len() - 1) as f64;
    let covariance = sum_xy / denom;
    let variance_x = sum_x2 / denom;
    let variance_y = sum_y2 / denom;
    Ok(covariance / (variance_x.sqrt() * variance_y.sqrt()))
}

catalogue/kit::pairs.text:
/// The pairs of numbers two arguments hold at the same positions, for the paired statistics:
/// arguments of different cell counts are #N/A; a position where either holds no number is
/// skipped (direct scalars follow `scalars`); the first error in reading order
/// (the first argument's before the second's at a position) is the result.
pub(super) fn pairs(
    site: &Site<'_>,
    arguments: &[CalcValue],
    x: usize,
    y: usize,
    scalars: PairScalars,
    services: &mut EvalServices<'_>,
) -> Step<Vec<(f64, f64)>> {
    let left = grid(site, arguments, x, services)?;
    let right = grid(site, arguments, y, services)?;
    if left.cells.len() != right.cells.len() {
        return fail(WorksheetErrorCode::NA);
    }
    let mut found = Vec::new();
    for (a, b) in left.cells.iter().zip(&right.cells) {
        let skip_nonnumeric = matches!(scalars, PairScalars::SkipNonnumeric);
        let a = grid_number(site, x, left.held || skip_nonnumeric, a)?;
        let b = grid_number(site, y, right.held || skip_nonnumeric, b)?;
        if let (Some(a), Some(b)) = (a, b) {
            found.push((a, b));
        }
    }
    Ok(found)
}

