    // |x| >= 1 from the cancellation-safe expm1 difference below that boundary.
    if n.abs() >= 1.0 {
        return crate::ported::excel_numeric::excel_x87_sub(
            crate::ported::excel_numeric::excel_exp(n),
            crate::ported::excel_numeric::excel_exp(-n),
