fn same_label(a: &[u16], b: &[u16]) -> bool {
    use crate::ported::text_kernels::fold_unit;
    a.len() == b.len() && a.iter().zip(b).all(|(&x, &y)| fold_unit(x) == fold_unit(y))
}

