fn sample_mean(values: &[f64]) -> Result<f64, WorksheetErrorCode> {
    if values.is_empty() {
        return Err(WorksheetErrorCode::Div0);
    }
    Ok(values.iter().sum::<f64>() / values.len() as f64)
}

fn sample_variance(values: &[f64]) -> Result<f64, WorksheetErrorCode> {
    if values.len() < 2 {
        return Err(WorksheetErrorCode::Div0);
    }
    let mean = sample_mean(values)?;
    Ok(values
        .iter()
        .map(|v| {
            let d = *v - mean;
            d * d
        })
        .sum::<f64>()
        / (values.len() - 1) as f64)
}

ported/statistical_tests_family::f_test_.text:
pub(crate) fn f_test_kernel(array1: &[f64], array2: &[f64]) -> Result<f64, WorksheetErrorCode> {
    if array1.len() < 2 || array2.len() < 2 {
        return Err(WorksheetErrorCode::Div0);
    }
    let var1 = sample_variance(array1)?;
    let var2 = sample_variance(array2)?;
    if var1 == 0.0 || var2 == 0.0 {
        return Err(WorksheetErrorCode::Div0);
    }
    let (ratio, df1, df2) = if var1 >= var2 {
        (
            var1 / var2,
            (array1.len() - 1) as f64,
            (array2.len() - 1) as f64,
        )
    } else {
        (
            var2 / var1,
            (array2.len() - 1) as f64,
            (array1.len() - 1) as f64,
        )
    };
    Ok((2.0 * f_dist_rt_kernel(ratio, df1, df2)?).min(1.0))
}

ported/fact::fact_reverse_product.text:
fn fact_reverse_product(n: i64) -> f64 {
    // Live Excel 16.0 b20326: FACT(n) is the reverse native product
    // n*(n-1)*...*2 (empty product 1 for n<=1). Forward product diverges
    // (FACT(170) forward misses). FACT(171) still overflows to #NUM!.
    if n <= 1 {
        return 1.0;
    }
    let mut acc = 1.0;
    for k in (2..=n).rev() {
        acc *= k as f64;
    }
    acc
}

ported/fact::fact_kernel.text:
pub fn fact_kernel(n: f64) -> Result<f64, WorksheetErrorCode> {
    // Excel checks the original sign before truncation: FACT(-0.1) is #NUM!,
    // while FACTDOUBLE deliberately has a different negative-domain rule.
    // Bound the product before converting to an integer, including huge inputs.
    if !n.is_finite() || n >= 171.0 {
        return Err(WorksheetErrorCode::Num);
    }
    let truncated = trunc_nonnegative(n)?;
    ExcelRealPolicy::FINITE
        .publish(n, fact_reverse_product(truncated))
}

