fn sort_entries(site: &Site<'_>, a: &[CalcValue], index: usize) -> Step<Vec<i64>> {
    let Some(value) = a.get(index) else {
        return Ok(Vec::new());
    };
    if value.is_missing() {
        return Ok(Vec::new());
    }
    let cells: Vec<CalcValue> = match value.core_ref() {
        CoreRef::Array(array) => array.iter_row_major().cloned().collect(),
        _ => vec![value.clone()],
    };
    let mut out = Vec::new();
