fn transpose(&self) -> Self {
    let mut values = vec![0.0; self.rows * self.cols];
    for row in 0..self.rows {
        for col in 0..self.cols {
            values[col * self.rows + row] = self.cell(row, col);
        }
    }
    Self {
        rows: self.cols,
        cols: self.rows,
        values,
    }
}

