pub(crate) fn eval_growth_surface(
    args: &[CalcValue]
) -> Result<CalcValue, WorksheetErrorCode> {
    let known_y = collect_numeric_vector_arg(&args[0])?;
    let known_x_raw = args
        .get(1)
        .filter(|arg| !matches!(arg.core_ref(), CoreRef::Missing))
        .map(|arg| collect_numeric_matrix_arg(arg))
        .transpose()?;
    let known_x = predictor_input_from_optional(known_x_raw, &known_y)?;
    let new_x_raw = args
        .get(2)
        .filter(|arg| !matches!(arg.core_ref(), CoreRef::Missing))
        .map(|arg| collect_numeric_matrix_arg(arg))
        .transpose()?;
    let new_x = prediction_input_from_optional(new_x_raw, &known_y, &known_x)?;
    let use_const =
        bool_flag_from_eval_or_default(optional_arg_value(args.get(3))?, true)?;
    growth_kernel(&known_y, &known_x, &new_x, use_const)
}

catalogue/statistics::entry::HARMEAN.text:
4 harmean "HARMEAN" (1, 255) [R "number1", R "number2"] |s, a, sv| {
    direct_first(s, a)?;
    let values = all(s, a, sv, Held::Numbers)?;
    let mut reciprocal_sum = 0.0;
    for v in &values {
        if *v <= 0.0 {
            return fail(WorksheetErrorCode::Num);
        }
        reciprocal_sum = k::excel_numeric::excel_x87_add(
            reciprocal_sum,
            k::excel_numeric::excel_x87_recip(*v),
        );
    }
    if values.is_empty() {
        return fail(WorksheetErrorCode::NA);
    }
    if !reciprocal_sum.is_finite() {
        return fail(WorksheetErrorCode::Num);
    }
    let average = k::excel_numeric::excel_x87_div(reciprocal_sum, values.len() as f64);
    s.number(k::excel_numeric::excel_x87_recip(average))
}

