catalogue/reference_text::resolved.text:
/// INDIRECT's result. `ref_text` is read as text (a number or a logical as its text, a blank
/// cell or an omitted argument as empty text) and `a1` as a logical (omitted from the call: TRUE;
/// written but omitted, or a blank cell: FALSE); an error of `ref_text`, and then of `a1`, is the
/// result before any text is resolved. Text that names no reference is #REF!.
fn resolved(
    site: &Site<'_>,
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Step<CalcValue> {
    site.scalar_operands(arguments)?;
    let text = site.argument(0, coerce::text(&arguments[0]))?;
    let a1 = match arguments.get(1) {
        None => true,
        Some(a1) => site.argument(1, coerce::logical(a1))?,
    };
    let Some(resolution) = services.reference_text() else {
        return Err(site.not_modelled(Some(0)));
    };
    match resolution.resolve(&text, a1) {
        TextReference::Area(area) => Ok(CalcValue::reference(ReferenceLike::area(area))),
        TextReference::Invalid => Err(Exit::Error(WorksheetErrorCode::Ref)),
        TextReference::NotModelled => Err(site.not_modelled(Some(0))),
    }
}

catalogue/rounding::int.text:
/// INT: the largest integer not above the number read to 15 significant digits
/// ([`ExactDecimal::fifteen`]) when it is below 1E15 in magnitude, and not above its binary64
/// otherwise (dc-bd5, Excel 16.0.20527 through COM on 2026-10-30, 109 readings:
/// INT(2.9999999999999996) and INT(2.9999999999999982) are 3, INT(123456789012345.67) is
/// 123456789012346, INT(-3.0000000000000004) is -3, INT(999999999999999.5) is 1E15, while
/// INT(4503599627370495.5) is 4503599627370495).
fn int(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    numeric(INT, arguments, services, |site, n| {
        let x = n[0];
        if x.abs() >= 1e15 {
            return Ok(decimal::floor(x));
        }
        match ExactDecimal::fifteen(x) {
            (reading, true) => match reading.round_at(0, Direction::TowardZero) {
                Some(whole) => {
                    let whole = site.nearest(&whole)?;
                    let read = site.nearest(&reading)?;
                    // Toward zero, one less for a negative reading with a fraction.
                    Ok(if read < whole { whole - 1.0 } else { whole })
                }
                None => site.nearest(&reading),
            },
            (_, false) => Ok(decimal::floor(x)),
        }
    })
}

