/// The fifteen significant digits the rounding functions round: the x87 reading where it is
/// known ([`ExactDecimal::fifteen_x87`]), and otherwise the number read to fifteen significant
/// digits, a half away from zero ([`ExactDecimal::fifteen`]).
fn reading(number: f64, ties_up: bool) -> ExactDecimal {
    ExactDecimal::fifteen_x87(number, ties_up).unwrap_or_else(|| ExactDecimal::fifteen(number).0)
}

decimal::Natural::add.text:
/// self + other.
pub(crate) fn add(&mut self, other: &Natural) {
    if self.limbs.len() < other.limbs.len() {
        self.limbs.resize(other.limbs.len(), 0);
    }
    let mut carry = 0u64;
    for (at, limb) in self.limbs.iter_mut().enumerate() {
        let sum =
            u64::from(*limb) + u64::from(other.limbs.get(at).copied().unwrap_or(0)) + carry;
        *limb = low32(sum);
        carry = sum >> 32;
    }
    if carry != 0 {
        self.limbs.push(low32(carry));
    }
}

decimal::Natural::subtract.text:
/// self - other, where other is at most self.
pub(crate) fn subtract(&mut self, other: &Natural) {
    debug_assert!(*self >= *other, "a natural subtracted from a smaller one");
    let mut borrow = 0u64;
    for (at, limb) in self.limbs.iter_mut().enumerate() {
        let taken = u64::from(other.limbs.get(at).copied().unwrap_or(0)) + borrow;
        let current = u64::from(*limb);
        if current >= taken {
            *limb = low32(current - taken);
            borrow = 0;
        } else {
            *limb = low32((1u64 << 32) + current - taken);
            borrow = 1;
        }
    }
    self.normalize();
}

decimal::Natural::bit_len.text:
fn bit_len(&self) -> usize {
    match self.limbs.last() {
        None => 0,
        Some(top) => {
            (self.limbs.len() - 1) * 32
                + usize::try_from(32 - top.leading_zeros()).expect("a bit count")
        }
    }
}

