/// The value when it is below 2^128.
fn to_u128(&self) -> Option<u128> {
    (self.limbs.len() <= 4).then(|| {
        self.limbs
            .iter()
            .rev()
            .fold(0u128, |value, &limb| (value << 32) | u128::from(limb))
    })
}

