fn iso_weeknum_serial(serial: i64) -> Result<f64, W> {
    let weekday_monday = weekday_of(serial, 2)? as i64;
    let thursday = serial + (4 - weekday_monday);
    let (iso_year, _, _) =
        ymd_from_excel_serial(DateSystem::System1900, thursday as f64).ok_or(W::Num)?;
