ported/gcd_lcm_common::lcm_int.text:
pub fn lcm_int(a: i64, b: i64) -> Result<i64, WorksheetErrorCode> {
    if a == 0 || b == 0 {
        Ok(0)
    } else {
        // Each admitted operand is at most 2^53, so the exact product fits
        // u128. Publish its binary64 rounding before checking the next step.
        // In particular, 2^53 + 1 rounds to the admitted boundary 2^53.
        let product = (a / gcd_int(a, b)) as u128 * b as u128;
        let rounded = product as f64;
        if rounded > GCD_LCM_LIMIT {
            Err(WorksheetErrorCode::Num)
        } else {
            Ok(rounded as i64)
        }
    }
}

ported/lcm_fn::lcm_kernel.text:
pub fn lcm_kernel(items: &[i64]) -> Result<f64, WorksheetErrorCode> {
    if items.contains(&0) {
        return Ok(0.0);
    }
    // Excel reduces the flattened values in reverse worksheet/argument order.
    // Rounded intermediates at 2^53 make this order observable.
    items
        .iter()
        .rev()
        .copied()
        .try_fold(1, lcm_int)
        .map(|n| n as f64)
}

