/// RANK's number: a number as it is, an error as itself, anything else #N/A.
fn rank_number(a: &[CalcValue]) -> Step<f64> {
    match a[0].core_ref() {
        CoreRef::Number(n) => Ok(n),
        CoreRef::Error(code) => fail(code),
        _ => fail(WorksheetErrorCode::NA),
    }
