fn should_ignore_cell(cell: &CalcValue, ignore_mode: usize) -> bool {
    match ignore_mode {
        0 => false,
        1 => matches!(cell.core_ref(), CoreRef::Empty | CoreRef::Missing),
        2 => matches!(cell.core_ref(), CoreRef::Error(_)),
        3 => matches!(
            cell.core_ref(),
            CoreRef::Empty | CoreRef::Missing | CoreRef::Error(_)
        ),
        _ => false,
    }
}

